begin;
create extension if not exists pgtap with schema extensions;
set local search_path=extensions,public,ml_private,ml_public;
select plan(8);
insert into auth.users(id,email) values('fb110000-0000-4000-8000-000000000001','garment-audit-qa@example.test');
select set_config('request.jwt.claims','{"sub":"fb110000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
create temporary table qa_studio(id uuid);
insert into qa_studio select ml_private.complete_studio_setup('Garment audit QA','America/Los_Angeles','cm','USD','en-US');
select ml_private.commit_canonical_operation('fb130000-0000-4000-8000-000000000001',(select id from qa_studio),'fb140000-0000-4000-8000-000000000001','user','[{"entityType":"garments","entityId":"fb140000-0000-4000-8000-000000000001","action":"insert","baseRevision":null,"row":{"title":"App-created draft","garment_code":"QA-APP"}},{"entityType":"tasks","entityId":"fb150000-0000-4000-8000-000000000001","action":"insert","baseRevision":null,"row":{"title":"Attached task","garment_id":"fb140000-0000-4000-8000-000000000001"}}]');
create temporary table qa_history_before as select id, to_jsonb(e)-'garment_id' as payload from ml_private.change_events e where garment_id='fb140000-0000-4000-8000-000000000001';
select is(ml_private.delete_studio_item((select id from qa_studio),'garment','fb140000-0000-4000-8000-000000000001',1,'fb130000-0000-4000-8000-000000000002')->>'status','applied','app-created editable garment deletion is acknowledged');
select is((select count(*) from ml_private.garments where studio_id=(select id from qa_studio)),0::bigint,'garment is removed');
select is((select count(*) from ml_private.tasks where studio_id=(select id from qa_studio)),0::bigint,'editable attached task is removed');
select is((select count(*) from qa_history_before b join ml_private.change_events e on e.id=b.id where to_jsonb(e)-'garment_id'=b.payload and e.garment_id is null),2::bigint,'all original activity payloads are preserved with only the live pointer cleared');
select is((select count(*) from ml_private.canonical_operation_receipts where id='fb130000-0000-4000-8000-000000000001' and garment_id is null),1::bigint,'original operation receipt is preserved');
select is(ml_private.delete_studio_item((select id from qa_studio),'garment','fb140000-0000-4000-8000-000000000001',1,'fb130000-0000-4000-8000-000000000002')->>'status','duplicate','deletion retry remains idempotent');
select ml_private.commit_canonical_operation('fb130000-0000-4000-8000-000000000003',(select id from qa_studio),'fb140000-0000-4000-8000-000000000003','user','[{"entityType":"garments","entityId":"fb140000-0000-4000-8000-000000000003","action":"insert","baseRevision":null,"row":{"title":"Keep this garment","garment_code":"QA-KEEP"}}]');
reset role;
select throws_ok($q$update ml_private.change_events set garment_id=null where garment_id='fb140000-0000-4000-8000-000000000003'$q$,'23514','Version history is append-only; create a new event or Freeze Frame.','direct clearing of a live history pointer stays forbidden');
select throws_ok($q$update ml_private.change_events set json_patch='[]'::jsonb where id in(select id from qa_history_before)$q$,'23514','Version history is append-only; create a new event or Freeze Frame.','history payload edits stay forbidden after garment deletion');
select * from finish();
rollback;
